import{_ as i,a8 as o,o as n,c,ah as a,K as t}from"./chunks/framework.D31WLDJp.js";import"./chunks/theme.CP9whvzN.js";const m=JSON.parse('{"title":"小红书自动化登录与 Cookie 复用","description":"","frontmatter":{"type":"lesson","scope":"xhs-content","created":"2026-09-13T00:00:00.000Z","updated":"2026-09-13T00:00:00.000Z","tags":["小红书","自动化","cookie","playwright","edge","踩坑"]},"headers":[],"relativePath":"vault/Memory/Lessons/小红书自动化登录与Cookie复用.md","filePath":"vault/Memory/Lessons/小红书自动化登录与Cookie复用.md","lastUpdated":1789374053000}'),d={name:"vault/Memory/Lessons/小红书自动化登录与Cookie复用.md"};function l(_,e,g,p,k,u){const s=o("NolebaseGitContributors"),r=o("NolebaseGitChangelog");return n(),c("div",null,[e[0]||(e[0]=a('<h1 id="小红书自动化登录与-cookie-复用" tabindex="-1">小红书自动化登录与 Cookie 复用 <a class="header-anchor" href="#小红书自动化登录与-cookie-复用" aria-label="Permalink to “小红书自动化登录与 Cookie 复用”">​</a></h1><p><strong>Why:</strong> 小红书反爬强：未登录页不放内容，且对自动化浏览器有风控；每次扫码成本高，工具链必须一次登录、长期复用。</p><p><strong>How to apply:</strong></p><ol><li><strong>networkidle 永不触发</strong>：小红书页面持续轮询（二维码刷新/埋点），Playwright <code>wait_for_load_state(&#39;networkidle&#39;)</code> 必然超时。封装为 try/except 的&quot;尽力等待&quot;，超时不算失败。scraper.py 已修（<code>wait_idle_lenient</code>）。</li><li><strong>运行中的 Edge/Chrome 独占锁定 cookie 库</strong>：<code>Default/Network/Cookies</code> 无法被 cp/esentutl 读取（JET_errFileAccessDenied）。唯一办法是彻底关闭浏览器后拷贝。</li><li><strong>cookie 复用方案（免扫码）</strong>：关闭 Edge → 拷贝 <code>User Data/Local State</code>、<code>Default/Network/</code>、<code>Default/Preferences</code> 到迷你 profile（如 <code>C:\\Users\\stars\\.xhs-edge-profile</code>）→ Playwright <code>launch_persistent_context(profile, channel=&#39;msedge&#39;)</code> 启动真 Edge 内核解密 cookie。9.6G 用户目录无需整拷，三个文件即可。用户日常 Edge 可照常重开，两边互不影响。</li><li><strong>勿混用两份会话</strong>：持久化 profile 自带登录态时，跳过加载外部 cookies.json，否则旧 cookie 会按 name+domain 覆盖有效会话，导致跳转登录页（2026-09-13 实踩）。</li><li><strong>redbook CLI 无法读 Edge</strong>：<code>--cookie-source</code> 只支持 chrome/safari/firefox；用 scraper 保存的 cookies.json 拼 cookie-string（<code>a1=...; web_session=...</code>）喂给 <code>--cookie-string</code> 或 <code>redbook auth save</code>。</li><li>抓取频率保持&quot;普通用户浏览&quot;节奏（滚动间隔、单账号单次），避免触发风控。</li><li><strong>主页/详情链接必须带 <code>xsec_token</code></strong>，缺失则重定向登录页（即使 cookie 有效）。从 App/网页分享链接里复制完整链接。</li><li><strong>游客态 SSR 的 noteId 被清空</strong>：标题/点赞/时间/封面/token 都有，唯独 ID 空白 → 无法构造详情页 URL。且同一页面反复访问后会从 SSR 降级为空数据+验证码（约 8 次内触发）。</li><li><strong>Edge 会话会轮换</strong>：从磁盘拷出的 web_session 可能已被轮换，API 侧仍认（redbook user-info 正常）但 Web 前端拒绝（弹登录墙）。工具浏览器要用自己的扫码会话，不要依赖拷贝。</li><li><strong>小红书对 CDP 自动化的检测深于 navigator.webdriver</strong>：隐藏 webdriver 后前端仍视为未登录。结论：别死磕游客态浏览器路线，一次扫码登录是最短路径。</li><li><strong>风控是间歇性静默限流</strong>（2026-09-13 实测）：登录态下 <code>user_posted</code> API 同一代码时有时无——成功返回 13KB 数据后约 40 分钟，同参数请求即不再出现该 API（无报错、无验证码弹窗、页面正常渲染但笔记区空）。redcaptcha getconfig 是前置风控检查，出现即意味着被盯上。<strong>正确应对：立即停手等冷却（小时级），频繁重试会加重标记</strong>。下次运行先跑一次轻量探测（单次打开主页观察 user_posted 是否出现），确认解禁再跑归档。</li><li><strong>登录态数据链路已验证</strong>：登录后主页笔记不走 SSR（<code>__INITIAL_STATE__.user.notes</code> 为空），走 <code>user_posted</code> API（<code>/api/sns/web/v1/user_posted?user_id=...&amp;xsec_token=...</code>，响应 <code>data.notes[]</code> 含 note_id/display_title/liked_count/xsec_token/cover）。xhs_archive.py 已实现该拦截，只需风控解禁即可跑通。</li></ol>',4)),t(s),t(r)])}const C=i(d,[["render",l]]);export{m as __pageData,C as default};
